using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;
using F = StrataLint.Scribe.FormulaDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Observer.ProbabilisticClosure.TrajectoryLaws;

internal sealed class RarePriorFairBitServiceDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Observer/ProbabilisticClosure/TrajectoryLaws/RarePriorFairBitService.";
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "RarePriorFairBitService", H("RarePriorFairBitService"), Blocks(
                Paragraph(Text("The service holds a threshold tag, PC, Fin 7 position, Fin 128 candidate and one output bit. Reset clears the registers. Only a bit instruction reads fresh randomness. Seven sequential fair bits produce a binary candidate; comparison accepts 0 through 99 and tests the fixed thresholds 40, 90 and 1. Rejection clears both candidate and position and returns to reset without retaining a retry number.")),
                Paragraph(Text("The packet law is the product of seven fair Bernoulli bit measures. Independent packet streams retain all infinite paths. Rejection has probability 28/128=7/32, so finite rejection survival is (7/32) to the m. Actual first-return alpha cylinders are disjoint; summing their product masses gives 2/5, 9/10 and 1/100. The service trajectory either remains at reset after a rejected prefix or retains its first accepted result. Its eventual alpha output event equals the union of these first-return cylinders.")),
                Paragraph(Text("A paused bit instruction consumes precisely its remaining bits. Its first partial trial either returns or resets; every subsequent rejected trial is a fresh canonical packet. The actual never-return event is contained in the shifted infinite rejection event of measure zero. This argument covers every service microstate, including comparison, partial candidates, reset and already returned states. Individual transitions use only weights 0, 1/2 and 1.")),
                Node("seven-bit-candidate", "seven_bit_candidate", "seven bit candidate", "Successive binary shifts assemble the seven fresh bits into the addressed Fin 128 candidate and enter comparison."),
                Node("packet-transaction", "packet_transaction", "packet transaction", "Comparison accepts candidates below 100, returns the threshold color, or clears the candidate and position and enters reset."),
                Node("microstep-weights", "microstep_weights", "microstep weights", "A bit step is the sum of two half-weight deterministic images; every other instruction has a single unit-weight image."),
                Node("fair-packet-mass", "fair_packet_mass", "fair packet mass", "The seven independent fair singleton masses multiply to one over 128 for every packet."),
                Node("packet-law-singleton", "packet_law_singleton", "Packet singleton law", "The existing packet measure assigns one over 128 to each singleton. RarePriorSerialExecution uses this original supplier in its vector packet law and positive acceptance proof."),
                Node("survival-geometric", "survival_geometric", "survival geometric", "Exactly 28 of the 128 packet addresses reject. Iterating the rejection recurrence multiplies survival by seven over 32."),
                Node("exact-service-law", "exact_service_law", "exact service law", "Summing the geometric first-return masses gives the three threshold fractions. The rejection survival tends to zero."),
                Node("actual-survival-probability", "actual_survival_probability", "actual survival probability", "Independent stream cylinders requiring m rejected packets have measure equal to the mth power of seven over 32."),
                Node("almost-sure-service-return", "almost_sure_service_return", "almost sure service return", "Continuity of measure for the decreasing rejection cylinders gives zero measure to infinite rejection."),
                Node("actual-service-output-law", "actual_service_output_law", "actual service output law", "Disjoint first-alpha-return cylinders have the computed product masses, whose countable sum is the returned alpha mass."),
                Node("every-microstate-returns", "every_microstate_returns", "every microstate returns", "The first partial trial either returns or resets. Any subsequent nonreturning trajectory lies in a shifted infinite rejection event of measure zero."),
                Node("rational-service-realization", "rational_service_realization", "rational service realization", "The measured first-return law, allowed microstep weights and almost-sure return hold together for the explicit service."),
                Node("prefix-reset", "prefix_reset", "Rejected prefix resets", "Every finite rejected prefix leaves the actual trialRun at its prescribed reset entry. RarePriorSerialExecution uses this original supplier to identify the returned service after the first accepted packet."),
                Node("operational-service-realization", "operational_service_realization", "operational service realization", "The canonical trajectory retains the first accepted result. Its eventual alpha output event equals the cylinder union, transferring the exact probability calculation to operational output."))));

    private static DocumentBlock.Describe Node(string id, string name, string title, string body) =>
        Describe.Lean(DescribeId.Create(id), DeclarationHandle.Create(Prefix + name), H(title),
            StatementSource.FromAuthor(Disp(Statement(name))), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text(body))), DescribeRole.Theorem);

