        "prefix_reset" => Seq(Forall, Sp, Open, Name("t"), Sp, Colon, Sp, Name("Threshold"), Close, Sp, Comma, Sp, Forall, Sp, Open, Name("omega"), Sp, Colon, Sp, Seq(Mathbb, Grp(F.Id("N"))), Sp, To, Sp, Name("Packet"), Close, Sp, Comma, Sp, Forall, Sp, Open, Name("m"), Sp, Colon, Sp, Seq(Mathbb, Grp(F.Id("N"))), Close, Sp, Comma, Sp, Open, Forall, Sp, Name("j"), Sp, Lt, Sp, Name("m"), Sp, Comma, Sp, D(1, 0, 0), Sp, Leq, Sp, Open, Name("packetEquiv"), Sp, Open, Name("omega"), Sp, Name("j"), Close, Close, Dot, Name("val"), Close, Sp, To, Sp, Name("trialRun"), Sp, Open, Name("entry"), Sp, Name("t"), Close, Sp, Name("omega"), Sp, Name("m"), Sp, Eq, Sp, Name("entry"), Sp, Name("t")),
