        "exact_service_law" => Seq(Name("returnedAlphaMass"), Sp, Dot, Sp, Name("ordinary"), Sp, Eq, Sp, D(2), Sp, Slash, Sp, D(5), Sp, Land, Sp, Name("returnedAlphaMass"), Sp, Dot, Sp, Name("high"), Sp, Eq, Sp, D(9), Sp, Slash, Sp, D(1, 0), Sp, Land, Sp, Name("returnedAlphaMass"), Sp, Dot, Sp, Name("low"), Sp, Eq, Sp, D(1), Sp, Slash, Sp, D(1, 0, 0), Sp, Land, Sp, Name("Tendsto"), Sp, Name("survivalMass"), Sp, Name("atTop"), Sp, Open, Sp, Name("nhds"), Sp, D(0), Sp, Close),
