        "almost_sure_service_return" => Seq(Name("packetStreamLaw"), Sp, Open, Sp, Name("iInter"), Sp, Name("m"), Sp, Colon, Sp, Seq(Mathbb, Grp(F.Id("N"))), Sp, Comma, Sp, Name("survives"), Sp, Name("m"), Sp, Close, Sp, Eq, Sp, D(0)),
        "actual_service_output_law" => Seq(Forall, Sp, Open, Sp, Name("t"), Sp, Colon, Sp, Name("Threshold"), Sp, Close, Sp, Comma, Sp, Open, Sp, Name("packetStreamLaw"), Sp, Open, Sp, Name("iUnion"), Sp, Name("m"), Sp, Colon, Sp, Seq(Mathbb, Grp(F.Id("N"))), Sp, Comma, Sp, Name("alphaReturnEvent"), Sp, Name("t"), Sp, Name("m"), Sp, Close, Sp, Eq, Sp, Name("ENNReal"), Sp, Dot, Sp, Name("ofReal"), Sp, Open, Sp, Name("returnedAlphaMass"), Sp, Name("t"), Sp, Close, Sp, Close),
