        "rational_service_realization" => Seq(Forall, Sp, Open, Sp, Name("t"), Sp, Colon, Sp, Name("Threshold"), Sp, Close, Sp, Comma, Sp, Open, Sp, Name("packetStreamLaw"), Sp, Open, Sp, Name("iUnion"), Sp, Name("m"), Sp, Colon, Sp, Seq(Mathbb, Grp(F.Id("N"))), Sp, Comma, Sp, Name("alphaReturnEvent"), Sp, Name("t"), Sp, Name("m"), Sp, Close, Sp, Eq, Sp, Name("ENNReal"), Sp, Dot, Sp, Name("ofReal"), Sp, Open, Sp, Open, Sp, Name("threshold"), Sp, Name("t"), Sp, Close, Sp, Dot, Sp, Name("val"), Sp, Slash, Sp, Open, Sp, D(1, 0, 0), Sp, Colon, Sp, Seq(Mathbb, Grp(F.Id("R"))), Sp, Close, Sp, Close, Sp, Land, Sp, Open, Sp, Forall, Sp, Name("s"), Sp, Name("q"), Sp, Colon, Sp, Name("Service"), Sp, Comma, Sp, Name("microWeight"), Sp, Name("s"), Sp, Name("q"), Sp, Eq, Sp, D(0), Sp, Lor, Sp, Name("microWeight"), Sp, Name("s"), Sp, Name("q"), Sp, Eq, Sp, D(1), Sp, Slash, Sp, D(2), Sp, Lor, Sp, Name("microWeight"), Sp, Name("s"), Sp, Name("q"), Sp, Eq, Sp, D(1), Sp, Close, Sp, Land, Sp, Open, Sp, Forall, Sp, Name("s"), Sp, Colon, Sp, Name("Service"), Sp, Comma, Sp, Name("packetStreamLaw"), Sp, Open, Sp, Name("neverReturns"), Sp, Name("s"), Sp, Close, Sp, Eq, Sp, D(0), Sp, Close, Sp, Close),
